var P2={ "dsu-trace": "Process unions left to right: find both roots (following parent pointers), attach one root under the other if different. A union inside one set is a silent no-op — count it as redundant, not as an error. After all unions, each query is just 'same root?'. The final parent array tells the whole story." };
var P3={ "dsu-trace": "Components: {components}; query answers: {answers}. Self-check: components = n minus the number of SUCCESSFUL unions — recount your trace with that invariant." };
var PYPROG={ "dsu-trace": "TRACE_INPUT = {input}\nn = TRACE_INPUT['n']\nparent = list(range(n))\ndef find(x):\n    while parent[x] != x:\n        parent[x] = parent[parent[x]]; x = parent[x]\n    return x\nfor a, b in TRACE_INPUT['unions']:\n    ra, rb = find(a), find(b)\n    if ra != rb: parent[rb] = ra\ncomps = len({find(i) for i in range(n)})\nans = [find(a) == find(b) for a, b in TRACE_INPUT['queries']]\nprint({'components': comps, 'answers': ans})\n" };
